import { readFileSync } from "node:fs";

import { expect, sample, test, uniqueName } from "../../fixtures";

test.describe("vendor under review", () => {
  test("a vendor in review cannot be edited", { tag: "@VEN-09" }, async ({ apiAs }) => {
    // Arrange
    const member = await apiAs("member");
    const created = await member.post("/api/vendors", {
      data: { name: uniqueName("Acme Freight"), category: "logistics", contact_email: "ops@acme.example" },
    });
    expect(created.status(), await created.text()).toBe(201);
    const vendor = (await created.json()) as { id: string };

    const uploads: [string, string][] = [
      ["w9", "w9.txt"],
      ["insurance_certificate", "insurance_certificate.txt"],
      ["contract", "contract.txt"],
    ];
    for (const [kind, file] of uploads) {
      const res = await member.post(`/api/vendors/${vendor.id}/documents`, {
        multipart: {
          kind,
          file: { name: file, mimeType: "text/plain", buffer: readFileSync(sample(file)) },
        },
      });
      expect(res.status(), await res.text()).toBe(201);
    }

    // Documents are extracted in the background; wait until none are still processing.
    await expect
      .poll(
        async () => {
          const res = await member.get(`/api/vendors/${vendor.id}/documents`);
          const docs = (await res.json()) as { status: string }[];
          return docs.length === 3 && docs.every((d) => d.status !== "processing");
        },
        { timeout: 60_000 },
      )
      .toBe(true);

    const submitted = await member.post(`/api/vendors/${vendor.id}/submit`);
    expect(submitted.status(), await submitted.text()).toBe(200);
    expect(((await submitted.json()) as { status: string }).status).toBe("in_review");

    // Act
    const response = await member.patch(`/api/vendors/${vendor.id}`, {
      data: { contact_email: "billing@acmefreight.example" },
    });

    // Assert
    expect(response.status(), await response.text()).toBe(409);
    const body = (await response.json()) as { error: { code: string } };
    expect(body.error.code, await response.text()).toBe("vendor_locked");
  });
});
